CREATE TABLE users (user_id VARCHAR(36) PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(200) NOT NULL, role VARCHAR(40) NOT NULL, password_hash VARCHAR(100) NOT NULL, failed_login_count INT NOT NULL DEFAULT 0, locked_until VARCHAR(35), created_at VARCHAR(35) NOT NULL, updated_at VARCHAR(35) NOT NULL);
CREATE TABLE refresh_tokens (token_id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at VARCHAR(35) NOT NULL, revoked BIT NOT NULL DEFAULT 0, created_at VARCHAR(35) NOT NULL, CONSTRAINT fk_refresh_user FOREIGN KEY (user_id) REFERENCES users(user_id));
